import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Timetable() {
  const [timetable, setTimetable] = useState([]);
  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

  useEffect(() => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => setTimetable(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: '40px', backgroundColor: '#f4f7f5', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      <div style={{ textAlign: 'center', marginBottom: '40px' }}>
        <h1 style={{ color: '#15803d', fontSize: '32px', fontWeight: '800', margin: 0 }}>Aura Pen Education</h1>
        <p style={{ color: '#475569', fontSize: '16px', marginTop: '5px' }}>Official 2026 Class Timetable - Mirigama</p>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '30px', maxWidth: '1000px', margin: '0 auto' }}>
        {days.map(day => {
          const dayClasses = timetable.filter(item => item.day === day);
          if (dayClasses.length === 0) return null;

          return (
            <div key={day} style={{ backgroundColor: '#fff', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.03)', overflow: 'hidden', border: '1px solid #e2e8f0' }}>
              <div style={{ backgroundColor: '#15803d', padding: '15px 25px', color: '#fff', fontWeight: '700', fontSize: '18px' }}>
                📅 {day}
              </div>
              <div style={{ padding: '20px', overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                  <thead>
                    <tr style={{ borderBottom: '2px solid #cbd5e1', color: '#64748b', fontSize: '13px' }}>
                      <th style={{ padding: '10px' }}>Grade</th>
                      <th style={{ padding: '10px' }}>Subject</th>
                      <th style={{ padding: '10px' }}>Time Slot</th>
                      <th style={{ padding: '10px' }}>Lecturer / Teacher</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dayClasses.map((cls, index) => (
                      <tr key={index} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px', backgroundColor: index % 2 === 0 ? '#fff' : '#f8fafc' }}>
                        <td style={{ padding: '12px 10px', fontWeight: '600', color: '#15803d' }}>{cls.grade}</td>
                        <td style={{ padding: '12px 10px', color: '#1e293b', fontWeight: '500' }}>{cls.subject}</td>
                        <td style={{ padding: '12px 10px', color: '#475569' }}><span style={{ backgroundColor: '#f1f5f9', padding: '3px 8px', borderRadius: '6px', fontSize: '13px' }}>{cls.time_slot}</span></td>
                        <td style={{ padding: '12px 10px', color: '#334155' }}>👤 {cls.teacher}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
